def B(heading,body):return dict(type='paragraph',heading=heading,body=body)
def table(heading,columns,rows):return dict(type='table',heading=heading,columns=columns,rows=rows)
def worked(heading,prompt,steps,answer,diag=None):
 b=dict(type='worked',heading=heading,prompt=prompt,steps=steps,answer=answer)
 if diag:b['diagramId']=D(diag)
 return b
def fig(key):return dict(type='diagram',diagramId=D(key))
def new(key,title,unit,prereqs,core,example,caution,dimension='knowledge'):
 pack['nodes'].append(dict(id=N(key),unitId=f'{P}.unit.{unit}',title=title,dimension=dimension,prerequisites=[N(x) for x in prereqs],lesson=dict(core=core,example=example,caution=caution)))
def teach(key,goals,sourceIds,*blocks,related=()):
 n=next(n for n in pack['nodes'] if n['id']==N(key));n['lesson'].update(goals=goals,sourceIds=list(sourceIds),blocks=list(blocks))
 if related:n['lesson']['relatedNodeIds']=[N(x) for x in related]
new('polymer-foundation','高分子を読む3つの視点','polymer',('condensed','carboxyl-group','amino-group'),'単量体、繰返し単位、主鎖の結合を別々に見ると、製法・性質・計算をつなげて理解できる。','エチレンC₂H₄とPEの繰返し単位C₂H₄は組成が同じでも、単位は独立した分子ではない。','繰返し単位の端の線は隣の単位へ続く。括弧の外のnは原子数ではなく繰返し数。')
new('ptfe','PTFEとハロゲンを含む高分子','polymer',('addition-polymer','pvc'),'テトラフルオロエチレンCF₂=CF₂が付加重合してPTFEになる。繰返し単位は−CF₂−CF₂−。','繰返し単位C₂F₄の式量はC=12、F=19なら100。','PVCはC₂H₃Cl、PTFEはC₂F₄。単位の原子を勝手に取り替えない。')
new('pmma','PMMA：側基と主鎖のエステル','polymer',('addition-polymer','esterification'),'MMAのビニル部が付加重合してPMMAとなる。エステル基は側基にあり、主鎖はC−C。','単量体CH₂=C(CH₃)COOCH₃ → 単位−CH₂−C(CH₃)(COOCH₃)−。','エステルを含むだけで、PETのようなポリエステルの主鎖と決めない。')
new('pva','PVAと側基のけん化','fibers',('vinylon','saponification'),'ポリ酢酸ビニルの側基をけん化すると、炭素主鎖を残してポリビニルアルコールを得る。','PVAcの単位式量86 → PVAの単位式量44。','高分子の側基が反応しても、主鎖の重合度が必ず変わるわけではない。')
new('polymer-structure','鎖の並び方と材料の性質','polymer',('pe','thermo'),'分岐、鎖の配向、結晶領域、鎖間の力が材料の密度や強度、熱での変化に関係する。','分岐が少ないPEの鎖は規則的に並びやすい。','結晶性は重合方式の別名ではない。実際の物性は成形条件や添加剤にも依存する。')
new('polymer-recovery','構造式から単量体を逆算する','polymer',('pet','nylon66','addition-polymer'),'炭素主鎖の付加高分子は隣り合う炭素をC=Cへ戻す。エステル・アミド主鎖は連結部を加水分解して原料を戻す。','PMMAの側基エステルとPETの主鎖エステルでは、切ったときの主鎖の変化が違う。','原料を復元するときは、切断点にHやOHを補って原子価を満たす。',dimension='reasoning')
new('polymer-hydrolysis','高分子の加水分解を量で追う','polymer',('polymer-recovery','mole'),'切れる結合を数え、単位から生成物の物質量へ換算する。生成物の質量は、水を取り込むため元の高分子より大きくなりうる。','PETの単位192 gから、酸166 gとジオール62 gを得る近似。','末端を無視する近似と、有限鎖を正確に数える問題を混ぜない。',dimension='calculation')
new('polymer-average','発展：数平均・質量平均分子量','polymer',('polymer-degree',),'鎖の長さには分布がある。数で平均するMₙと、質量で重みづけするM_wは異なる。','同じ本数の10000と30000の鎖ならMₙ=20000、M_w=25000。','この発展事項では設問に定義式を示す。受験計算では指定された平均の意味に従う。',dimension='calculation')
new('cellulose-substitution','セルロース誘導体の置換度計算','fibers',('acetate','cellulose','mole'),'残基のOHは3個。OHのHをアセチル基へ置き換えると、1か所につき式量が42増える。','末端無視でセルロース162 → トリアセテート288。','反応の質量増加を酢酸の式量60としない。Hが置き換わるためCH₃CO−H=42。',dimension='calculation')
